#include <iostream>
#include <vector>
using namespace std;
int partition(vector<int>& a, int l, int h) {
    int pivot=a[h], i=l-1;
    for(int j=l;j<h;j++) if(a[j]<=pivot) swap(a[++i],a[j]);
    swap(a[i+1],a[h]); return i+1;
}
void quickSort(vector<int>& a,int l,int h){if(l<h){int p=partition(a,l,h);quickSort(a,l,p-1);quickSort(a,p+1,h);}}
